        "paramKind": {
            "apiVersion": "cps-dynamic-admission-live-20261008.compute.cps.unileoben.ac.at/v1alpha1",
            "kind": "DynamicGpuQuotaPolicy"
        },
        "validations": [
            {
                "expression": "request.namespace == \"cps-dynamic-admission-live-20261008\"",
                "message": "Only the isolated qualification namespace is in scope"
            },
            {
                "expression": "request.operation in ['CREATE','UPDATE','DELETE']",
                "message": "Only the explicitly modelled ConfigMap operations are permitted"
            },
            {
                "expression": "has(request.userInfo) \u0026\u0026 has(request.userInfo.username) \u0026\u0026 request.userInfo.username in params.writers",
                "message": "Every ConfigMap mutation requires an explicitly reviewed authenticated writer"
            },
            {
                "expression": "size(variables.records) == 1 \u0026\u0026 has(variables.record.name)",
                "message": "Every ConfigMap name requires an explicit reviewed record; labels cannot authorize writes"
            },
            {
                "expression": "(has(variables.record.physicalGpuMemoryMiB)) \u0026\u0026 (variables.record.physicalGpuMemoryMiB.matches('^(?:[1-9][0-9]{0,4}|1[0-2][0-9]{4}|130[0-9]{3}|1310[0-6][0-9]|13107[0-2])$')) \u0026\u0026 (has(variables.record.gpuPortion)) \u0026\u0026 (variables.record.gpuPortion.matches('^(?:0\\\\.[0-9]{1,8}|1)$')) \u0026\u0026 (double(variables.record.gpuPortion) \u003e 0) \u0026\u0026 (double(variables.record.gpuPortion) \u003c= 1) \u0026\u0026 (has(variables.record.runaiNumOfGpus)) \u0026\u0026 (variables.record.runaiNumOfGpus == variables.record.gpuPortion) \u0026\u0026 (has(variables.record.cudaDeviceMemoryLimit)) \u0026\u0026 (variables.record.cudaDeviceMemoryLimit.matches('^(?:[1-9][0-9]{0,3}|[1-3][0-9]{4}|40[0-8][0-9]{2}|409[0-5][0-9]|40960)m$')) \u0026\u0026 (variables.record.cudaDeviceMemoryLimit == string(int(double(variables.record.physicalGpuMemoryMiB) * double(variables.record.gpuPortion)) - (double(int(double(variables.record.physicalGpuMemoryMiB) * double(variables.record.gpuPortion))) \u003e (double(variables.record.physicalGpuMemoryMiB) * double(variables.record.gpuPortion)) ? 1 : 0)) + 'm')",
                "message": "The injected quota must match the reviewed bounded node-memory label and upstream float64 truncation"
            },
            {
                "expression": "(has(variables.subject.apiVersion)) \u0026\u0026 (variables.subject.apiVersion == 'v1') \u0026\u0026 (has(variables.subject.kind)) \u0026\u0026 (variables.subject.kind == 'ConfigMap') \u0026\u0026 (has(variables.subject.metadata)) \u0026\u0026 (has(variables.subject.metadata.name)) \u0026\u0026 (variables.subject.metadata.name == variables.record.name) \u0026\u0026 (has(variables.subject.metadata.namespace)) \u0026\u0026 (variables.subject.metadata.namespace == variables.record.namespace) \u0026\u0026 (variables.subject.metadata.namespace == request.namespace)",
                "message": "The exact registered namespace/name is required"
            },
            {
                "expression": "(has(variables.subject.metadata)) \u0026\u0026 (has(variables.subject.metadata.ownerReferences)) \u0026\u0026 (size(variables.subject.metadata.ownerReferences) == 1) \u0026\u0026 (variables.subject.metadata.ownerReferences.all(o, (has(o.apiVersion)) \u0026\u0026 (o.apiVersion == 'v1') \u0026\u0026 (has(o.kind)) \u0026\u0026 (o.kind == 'Pod') \u0026\u0026 (has(o.name)) \u0026\u0026 (o.name == variables.record.podName) \u0026\u0026 (has(o.uid)) \u0026\u0026 (o.uid == variables.record.podUid) \u0026\u0026 (!has(o.controller) || !o.controller) \u0026\u0026 (!has(o.blockOwnerDeletion) || !o.blockOwnerDeletion)))",
                "message": "Exactly the reviewed non-controller v1 Pod owner must remain attached"
            },
            {
                "expression": "!has(variables.subject.binaryData) \u0026\u0026 !has(variables.subject.immutable)",
                "message": "Binary data and immutable quota ConfigMaps are outside the reviewed contract"
            },
            {
                "expression": "(variables.record.type == 'evar' \u0026\u0026 size(variables.data) == 0) || (variables.record.type == 'capabilities' \u0026\u0026 variables.stage \u003e= 0)",
                "message": "Only the exact reviewed empty evar or staged capabilities values are permitted"
            },
            {
                "expression": "request.operation != 'CREATE' || (oldObject == null \u0026\u0026 size(variables.data) == 0 \u0026\u0026 !has(variables.record.cmUid))",
                "message": "Creation begins empty and cannot recreate an already UID-bound map"
            },
            {
                "expression": "request.operation != 'UPDATE' || ((has(oldObject.metadata)) \u0026\u0026 (has(oldObject.metadata.uid)) \u0026\u0026 (oldObject.metadata.uid.matches('^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$')) \u0026\u0026 (has(object.metadata)) \u0026\u0026 (has(object.metadata.uid)) \u0026\u0026 (object.metadata.uid == oldObject.metadata.uid) \u0026\u0026 (has(oldObject.metadata.name)) \u0026\u0026 (object.metadata.name == oldObject.metadata.name) \u0026\u0026 (has(oldObject.metadata.namespace)) \u0026\u0026 (object.metadata.namespace == oldObject.metadata.namespace) \u0026\u0026 (has(oldObject.metadata.ownerReferences)) \u0026\u0026 (object.metadata.ownerReferences == oldObject.metadata.ownerReferences) \u0026\u0026 (!has(oldObject.binaryData)) \u0026\u0026 (!has(oldObject.immutable)) \u0026\u0026 (!has(variables.record.cmUid) || object.metadata.uid == variables.record.cmUid))",
                "message": "Updates preserve the observed ConfigMap UID, name, namespace and exact owner references"
            },
            {
                "expression": "request.operation != 'UPDATE' || ((variables.record.type == 'evar' \u0026\u0026 size(variables.oldData) == 0) || (variables.record.type == 'capabilities' \u0026\u0026 variables.oldStage \u003e= 0 \u0026\u0026 variables.stage \u003e= variables.oldStage \u0026\u0026 variables.stage \u003c= variables.oldStage + 1))",
                "message": "Same-stage retries or one forward population step are allowed; reset, removal and skipped stages are denied"
            },
            {
                "expression": "request.operation != 'DELETE' || (has(oldObject.metadata) \u0026\u0026 has(oldObject.metadata.uid) \u0026\u0026 oldObject.metadata.uid.matches('^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$') \u0026\u0026 (!has(variables.record.cmUid) || oldObject.metadata.uid == variables.record.cmUid))",
                "message": "Reviewed binder rollback uses the exact old Pod-owned ConfigMap and optional independently pinned ConfigMap UID"
            }
        ],
        "variables": [
            {
                "expression": "request.operation == 'DELETE' ? oldObject : object",
                "name": "subject"
            },
            {
                "expression": "has(variables.subject.metadata) \u0026\u0026 has(variables.subject.metadata.name) ? params.records.filter(r, r.namespace == request.namespace \u0026\u0026 r.name == variables.subject.metadata.name) : []",
                "name": "records"
            },
            {
                "expression": "size(variables.records) == 1 ? variables.records[0] : {}",
                "name": "record"
            },
            {
                "expression": "has(variables.subject.data) ? variables.subject.data : {}",
                "name": "data"
            },
            {
                "expression": "has(oldObject.data) ? oldObject.data : {}",
                "name": "oldData"
            },
            {
                "expression": "size(variables.records) == 1 ? [{}, {'NVIDIA_VISIBLE_DEVICES': variables.record.visibleDevices}, {'NVIDIA_VISIBLE_DEVICES': variables.record.visibleDevices, 'GPU_PORTION': variables.record.gpuPortion, 'RUNAI_NUM_OF_GPUS': variables.record.runaiNumOfGpus}, {'NVIDIA_VISIBLE_DEVICES': variables.record.visibleDevices, 'GPU_PORTION': variables.record.gpuPortion, 'RUNAI_NUM_OF_GPUS': variables.record.runaiNumOfGpus, 'CUDA_DEVICE_MEMORY_LIMIT': variables.record.cudaDeviceMemoryLimit}] : [{},{},{},{}]",
                "name": "stages"
            },
            {
                "expression": "size(variables.data) == 0 ? 0 : variables.data == variables.stages[1] ? 1 : variables.data == variables.stages[2] ? 2 : variables.data == variables.stages[3] ? 3 : -1",
                "name": "stage"
            },
            {
                "expression": "!has(oldObject.metadata) ? -1 : (size(variables.oldData) == 0 ? 0 : variables.oldData == variables.stages[1] ? 1 : variables.oldData == variables.stages[2] ? 2 : variables.oldData == variables.stages[3] ? 3 : -1)",
                "name": "oldStage"
            }
        ]
    },
    "status": {}
}

